∀ {m : Type u → Type v} {n : Type u → Type w} [inst : Monad m] [inst_1 : Monad n] {lift : ⦃α : Type u⦄ → m α → n α}
  {α β : Type u} [LawfulMonad m] [LawfulMonad n] [Std.Internal.LawfulMonadLiftFunction lift] (mf : m (α → β))
  (ma : m α), lift (mf <*> ma) = lift mf <*> lift ma

∀ {m : Type u → Type v} {n : Type u → Type w} [inst : Monad m] [inst_1 : Monad n] {lift : ⦃α : Type u⦄ → m α → n α}
  {α β : Type u} [LawfulMonad m] [LawfulMonad n] [Std.Internal.LawfulMonadLiftFunction lift] (x : m α) (y : m β),
  lift (x <* y) = lift x <* lift y

∀ {m : Type u → Type v} {n : Type u → Type w} [inst : Monad m] [inst_1 : Monad n] {lift : ⦃α : Type u⦄ → m α → n α}
  {α β : Type u} [LawfulMonad m] [LawfulMonad n] [Std.Internal.LawfulMonadLiftFunction lift] (x : m α) (y : m β),
  lift (x *> y) = lift x *> lift y

∀ {α : Type u} (self : Std.Packages.LinearOrderOfLEArgs α),
  let this := self.le;
  let this_1 := self.decidableLE;
  let this_2 := self.max;
  ∀ (a b : α), max a b = if b ≤ a then a else b

∀ {α : Type u} (self : Std.Packages.LinearPreorderOfLEArgs α),
  let this := self.le;
  let this_1 := self.decidableLE;
  have this_2 := ⋯;
  let this_3 := self.ord;
  ∀ (a b : α), (compare a b).isGE = true ↔ b ≤ a

∀ {α : Type u} (self : Std.Packages.LinearPreorderOfOrdArgs α),
  let this := self.ord;
  let this_1 := self.le;
  have this_2 := ⋯;
  let this_3 := self.beq;
  ∀ (a b : α), (a == b) = true ↔ compare a b = Ordering.eq

∀ {α : Type u} (self : Std.Packages.LinearPreorderOfOrdArgs α),
  let this := self.ord;
  let this_1 := self.le;
  have this_2 := ⋯;
  let this_3 := self.lt;
  ∀ (a b : α), a < b ↔ compare a b = Ordering.lt

∀ {α : Type u} (self : Std.Packages.PreorderOfLEArgs α),
  let this := self.le;
  ∀ (a b c : α), a ≤ b → b ≤ c → a ≤ c
